/// Returns a database engine icon corresponding to the connection's driver.
/// Sized at 14px for clear legibility in the sidebar and lists.
pub fn database_icon(driver: &str, color: Rgba) -> Icon {
    database_icon_sized(driver, px(14.0), color)
}

/// Returns a database engine icon rendered with explicit sizing.
pub fn database_icon_sized(driver: &str, size: Pixels, color: Rgba) -> Icon {
    let lower = driver.trim().to_ascii_lowercase();
    let icon = match lower.as_str() {
        "postgres" | "postgresql" => Icon::default().data(POSTGRES_SVG),
        "sqlite" | "sqlite3" => Icon::default().data(SQLITE_SVG),
        "mysql" | "mariadb" => Icon::default().data(MYSQL_SVG),
        "oracle" => Icon::default().data(ORACLE_SVG),
        "mssql" | "sqlserver" => Icon::default().data(MSSQL_SVG),
        _ => Icon::new(IconName::Database),
    };
    icon.size(size).text_color(color)
}

#[cfg(test)]
mod tests {
    use super::*;
    use gpui::rgba;

    #[test]
    fn maps_known_driver_ids_to_icons() {
        let color = rgba(0xffffffff);
        let _pg = database_icon("postgres", color);
        let _sqlite = database_icon("sqlite", color);
        let _mysql = database_icon("mysql", color);
        let _oracle = database_icon("oracle", color);
        let _mssql = database_icon("mssql", color);
        let _fallback = database_icon("unknown_driver", color);

        let _pg_sized = database_icon_sized("postgres", px(16.0), color);
        let _sqlite_sized = database_icon_sized("sqlite", px(20.0), color);

        // Verify non-empty data on custom SVGs
        assert!(!POSTGRES_SVG.is_empty());
        assert!(!SQLITE_SVG.is_empty());
        assert!(!MYSQL_SVG.is_empty());
        assert!(!ORACLE_SVG.is_empty());
        assert!(!MSSQL_SVG.is_empty());
    }
}
